from pathlib import Path
r=Path(__file__).resolve().parent;d=(r/'design.json').read_text()
(r/'figma-plugin/manifest.json').write_text('''{"name":"BIG BEN Design Import","id":"bigben-design-import-2026","api":"1.0.0","main":"code.js","ui":"ui.html","editorType":["figma"],"documentAccess":"dynamic-page","networkAccess":{"allowedDomains":["none"]}}''')
code='''const DATA=__DATA__;
figma.showUI(__html__,{width:420,height:380});
let running=false;
function color(hex){return {r:parseInt(hex.slice(1,3),16)/255,g:parseInt(hex.slice(3,5),16)/255,b:parseInt(hex.slice(5,7),16)/255}}
function paint(hex){return [{type:'SOLID',color:color(hex)}]}
function bytes(base64){const chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';const text=base64.replace(/=+$/,'');const output=[];let buffer=0,bits=0;for(const ch of text){const v=chars.indexOf(ch);if(v<0)continue;buffer=(buffer<<6)|v;bits+=6;if(bits>=8){bits-=8;output.push((buffer>>bits)&255)}}return Uint8Array.from(output)}
async function fonts(){const all=await figma.listAvailableFontsAsync();const family=all.some(f=>f.fontName.family==='Inter')?'Inter':'Roboto';const result={};for(const weight of [400,500,600,700]){const matches=weight===400?['Regular']:weight===500?['Medium','Regular']:weight===600?['Semi Bold','SemiBold','Bold','Regular']:['Bold','Regular'];const available=all.filter(f=>f.fontName.family===family).map(f=>f.fontName);const selected=matches.map(style=>available.find(f=>f.style===style)).find(Boolean)||available[0];if(!selected)throw new Error('Не найден шрифт Inter или Roboto');await figma.loadFontAsync(selected);result[weight]=selected}const serif=all.find(f=>f.fontName.family==='Playfair Display'&&f.fontName.style==='Regular');result.serif=serif?serif.fontName:result[400];await figma.loadFontAsync(result.serif);return result}
function node(n,font,imageHash){let v;if(n.type==='rect'){v=figma.createRectangle();v.resize(n.w,n.h);v.cornerRadius=n.r;v.fills=paint(n.fill);if(n.stroke){v.strokes=paint(n.stroke);v.strokeWeight=1}v.name='Surface / '+n.fill}else if(n.type==='text'){v=figma.createText();v.fontName=n.serif?font.serif:(font[n.weight]||font[400]);v.fontSize=n.size;v.characters=n.text;v.fills=paint(n.fill);v.textAutoResize='WIDTH_AND_HEIGHT';v.name=n.text}else if(n.type==='image'){v=figma.createRectangle();v.resize(n.w,n.h);v.fills=[{type:'IMAGE',imageHash,scaleMode:'FILL'}];v.name='Campaign / illustration'}else if(n.type==='svg'){v=figma.createNodeFromSvg(n.svg);v.resize(n.w,n.h);v.name=n.name}else return null;v.x=n.x;v.y=n.y;return v}
async function systemPage(font){const page=figma.createPage();page.name='BIG BEN • Дизайн-система';const frame=figma.createFrame();page.appendChild(frame);frame.name='Цвета, типографика, компоненты';frame.resize(1440,1300);frame.fills=paint('#FAF8F5');const title=node({type:'text',x:80,y:70,text:'BIG BEN — система дизайна',size:44,fill:'#23211F',weight:400,serif:true},font);frame.appendChild(title);const colors=['#FAF8F5','#FFFFFF','#23211F','#77736E','#E5DFD7','#681E30','#F0EAE4','#426F50'];const names=['Canvas','Surface','Text','Muted','Border','Primary','Soft','Success'];const existing=await figma.getLocalPaintStylesAsync();for(let i=0;i<colors.length;i++){const swatch=node({type:'rect',x:80+i*155,y:180,w:130,h:110,fill:colors[i],r:6},font);frame.appendChild(swatch);frame.appendChild(node({type:'text',x:80+i*155,y:312,text:names[i],size:14,fill:'#23211F',weight:600},font));frame.appendChild(node({type:'text',x:80+i*155,y:338,text:colors[i],size:12,fill:'#77736E',weight:400},font));if(!existing.some(s=>s.name==='BIG BEN / '+names[i])){const style=figma.createPaintStyle();style.name='BIG BEN / '+names[i];style.paints=paint(colors[i])}}const textList=[['Заголовок — характер и спокойствие',48,true],['Заголовок раздела',36,true],['Основной текст и интерфейс',18,false],['Подписи, параметры, навигация',14,false]];let y=420;for(const [text,size,serif]of textList){frame.appendChild(node({type:'text',x:80,y,text,size,serif,fill:'#23211F',weight:400},font));y+=size+38}const ref=DATA.screens.find(s=>s.id==='ui-desktop');const sample=ref.nodes.filter(n=>n.y>=300&&n.y<640);for(const n of sample){const v=node({...n,y:n.y+430},font,null);if(v)frame.appendChild(v)}return page}
figma.ui.onmessage=async msg=>{if(msg.type!=='import'||running)return;running=true;try{const font=await fonts();const hash=figma.createImage(bytes(DATA.assets.hero)).hash;const page=figma.createPage();page.name='BIG BEN • Макеты';await figma.setCurrentPageAsync(page);const selected=DATA.screens.filter(s=>msg.device==='all'||s.mobile===(msg.device==='mobile'));const frames=[];let rowY=0,rowHeight=0;for(let i=0;i<selected.length;i++){const s=selected[i];const col=i%4;if(col===0&&i){rowY+=rowHeight+120;rowHeight=0}const frame=figma.createFrame();page.appendChild(frame);frame.name=s.title+' / '+(s.mobile?'390 Mobile':'1440 Desktop');frame.resize(s.width,s.height);frame.x=col*1570;frame.y=rowY;frame.fills=paint('#FAF8F5');frame.clipsContent=true;for(const n of s.nodes){const v=node(n,font,hash);if(v)frame.appendChild(v)}frames.push(frame);rowHeight=Math.max(rowHeight,s.height);figma.ui.postMessage({type:'progress',value:i+1,total:selected.length});await new Promise(resolve=>setTimeout(resolve,1))}await systemPage(font);await figma.setCurrentPageAsync(page);figma.currentPage.selection=frames.slice(0,1);figma.viewport.scrollAndZoomIntoView(frames.slice(0,1));figma.ui.postMessage({type:'done',total:selected.length});figma.notify('Готово: '+selected.length+' редактируемых экранов')}catch(error){figma.ui.postMessage({type:'error',message:error.message});figma.notify(error.message,{error:true})}finally{running=false}};
'''
(r/'figma-plugin/code.js').write_text(code.replace('__DATA__',d))
(r/'figma-plugin/ui.html').write_text('''<!doctype html><html lang="ru"><meta charset="utf-8"><style>body{font:14px Arial;padding:20px;color:#23211f;background:#faf8f5}h1{font:28px Georgia;margin:0 0 18px}p{line-height:1.6;color:#77736e}select,button{width:100%;padding:13px;margin:8px 0;border:1px solid #ddd4cb;border-radius:5px}button{background:#681e30;color:#fff;cursor:pointer}button:disabled{opacity:.5}#status{font-size:12px;line-height:1.6}</style><h1>BIG BEN</h1><p>42 страницы, версии для компьютера и телефона. Настоящие редактируемые слои и отдельная дизайн-система.</p><label for="device">Какие экраны создать?</label><select id="device"><option value="all">Все 84 экрана</option><option value="desktop">42 экрана для компьютера</option><option value="mobile">42 экрана для телефона</option></select><button id="import">Создать экраны</button><div id="status">Без доступа к сети. Исходные данные товаров демонстрационные.</div><script>const button=document.querySelector('#import');button.onclick=()=>{button.disabled=true;parent.postMessage({pluginMessage:{type:'import',device:document.querySelector('#device').value}},'*')};onmessage=e=>{const m=e.data.pluginMessage;if(!m)return;document.querySelector('#status').textContent=m.type==='progress'?`Создаём экран ${m.value} из ${m.total}…`:m.type==='done'?`Готово: ${m.total} экранов. File → Save local copy сохранит .fig.`:'Ошибка: '+m.message;if(m.type!=='progress')button.disabled=false};</script></html>''')
